package com.hbm.client.radar;
import com.hbm.client.model.*;import com.hbm.machine.radar.RadarScreenBlockEntity;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;import org.joml.Matrix4f;
/** Exact original monitor mesh, world scanline and live entry/noise UVs atx=.38. */
public final class RadarDisplayRenderer implements BlockEntityRenderer<RadarScreenBlockEntity>{private static final ResourceLocation MODEL=ResourceLocation.parse("hbm:models/machines/radar_screen.obj"),TEXTURE=ResourceLocation.parse("hbm:textures/models/machines/radar_screen.png");public RadarDisplayRenderer(BlockEntityRendererProvider.Context c){}private static WavefrontMesh mesh(){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);}public static void model(PoseStack p,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.renderAll(mesh(),p,buffers.getBuffer(RenderType.entityCutoutNoCull(TEXTURE)),light,overlay,-1,LegacyObjRenderer.Convention.HFR_FLAT);}@Override public void render(RadarScreenBlockEntity screen,float partial,PoseStack p,MultiBufferSource buffers,int light,int overlay){float yaw=switch(DummyableBlock.facing(screen.getBlockState())){case NORTH->90;case WEST->180;case SOUTH->270;default->0;};LegacyContactShadows.render(screen,mesh(),new Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(yaw)),p,buffers);p.pushPose();p.translate(.5,0,.5);p.mulPose(Axis.YP.rotationDegrees(yaw));model(p,buffers,light,overlay);var m=p.last().pose();if(screen.linked){double offset=((screen.getLevel().getGameTime()%56)+partial)/30;var scan=buffers.getBuffer(RadarDisplayTypes.SCAN);scan.addVertex(m,.38F,(float)(2-offset),1.375F).setColor(0,255,0,0);scan.addVertex(m,.38F,(float)(2-offset),-.375F).setColor(0,255,0,0);scan.addVertex(m,.38F,(float)(2-offset-.125),-.375F).setColor(0,255,0,50);scan.addVertex(m,.38F,(float)(2-offset-.125),1.375F).setColor(0,255,0,50);var out=buffers.getBuffer(RadarDisplayTypes.LINKED);for(var e:screen.entries){double sx=(e.posX-screen.refX)/((double)screen.range+1)*.875,sz=(e.posZ-screen.refZ)/((double)screen.range+1)*.875,size=.0625;float u0=216/256F,u1=224/256F,v0=e.blipLevel*8/256F,v1=(e.blipLevel*8+8)/256F;vertex(out,m,1-sz+size,.5-sx+size,u0,v1);vertex(out,m,1-sz+size,.5-sx-size,u1,v1);vertex(out,m,1-sz-size,.5-sx-size,u1,v0);vertex(out,m,1-sz-size,.5-sx+size,u0,v0);}}else{int offset=118+screen.getLevel().random.nextInt(81);var out=buffers.getBuffer(RadarDisplayTypes.NOISE);vertex(out,m,1.875,1.375,216/256F,(offset+40)/256F);vertex(out,m,1.875,-.375,1,(offset+40)/256F);vertex(out,m,.125,-.375,1,offset/256F);vertex(out,m,.125,1.375,216/256F,offset/256F);}p.popPose();}private static void vertex(VertexConsumer out,org.joml.Matrix4f m,double y,double z,float u,float v){out.addVertex(m,.38F,(float)y,(float)z).setUv(u,v).setColor(-1);}@Override public boolean shouldRenderOffScreen(RadarScreenBlockEntity s){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(RadarScreenBlockEntity s){var p=s.getBlockPos();return new AABB(p.getX()-1,p.getY(),p.getZ()-1,p.getX()+2,p.getY()+2,p.getZ()+2);}}
